&lt;p data-path-to-node=&quot;5,11,0&quot;&gt;&lt;span data-path-to-node=&quot;5,11,0,1&quot;&gt;&lt;span class=&quot;citation-2840&quot;&gt;Drive security and quality initiatives across the organization and support certification audits&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
