&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;10,7,0&quot;&gt;&lt;span data-path-to-node=&quot;10,7,0,1&quot;&gt;&lt;span class=&quot;citation-2829&quot;&gt;Experience with Static Analysis and Secure Code Review implementations&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;10,8,0&quot;&gt;&lt;span data-path-to-node=&quot;10,8,0,1&quot;&gt;&lt;span class=&quot;citation-2828&quot;&gt;Sound knowledge of Linux systems, Kubernetes, Terraform, Vault, API, and web application security&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
